import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4, mix, smoothstep, texture, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const handlers = {};
  const timelines = [];
  const disposables = [];

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new ctx.THREE.Color(colors.ink ?? '#16161d');
  const paper = new ctx.THREE.Color(colors.paper ?? '#e8ecf2');
  const surface = new ctx.THREE.Color(colors.surface ?? '#0b0b10');

  const atlasRect = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const width = 3.2;
  const height = width / aspect;

  const geometry = new ctx.THREE.PlaneGeometry(width, height);

  const dummyData = new Uint8Array([255, 255, 255, 255]);
  const dummyTexture = new ctx.THREE.DataTexture(dummyData, 1, 1, ctx.THREE.RGBAFormat);
  dummyTexture.needsUpdate = true;
  disposables.push(dummyTexture);

  const uGrainTexture = uniform(dummyTexture);
  const uGrainIntensity = uniform(0.12);

  const uvNode = uv();
  const gradient = mix(color(surface), color(ink), smoothstep(0.0, 1.0, uvNode.y));
  const grainColor = texture(uGrainTexture, uvNode).rgb;
  const finalColor = mix(gradient, grainColor, uGrainIntensity);

  const material = new MeshBasicNodeMaterial({
    colorNode: vec4(finalColor, 1.0)
  });

  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      uGrainTexture.value = tex;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    if (!text) continue;
    const px = item.typography?.fontSize;
    const fontSizeUnit = px > 10 ? px / 150 : 0.34;

    const textObj = ctx.fontAtlas.createText(text, {
      fontSize: fontSizeUnit,
      color: colors.paper ?? '#e8ecf2',
      align: 'center'
    });
    textObj.position.z = 0.05;
    group.add(textObj);
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    if (ctx.primitives[primitive.name]) {
      const result = ctx.primitives[primitive.name](group, primitive.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  group.scale.set(0.98, 0.98, 0.98);
  group.position.y = 0.15;
  const tl = gsap.timeline();
  tl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, '-=0.6');
  timelines.push(tl);

  group.onBeforeRender = function(renderer, scene, camera) {
    group.lookAt(camera.position);
  };

  group.userData.handlers = handlers;
  group.userData.cleanup = () => {
    timelines.forEach(t => { try { t.kill(); } catch (e) {} });
    timelines.length = 0;
    group.onBeforeRender = null;
    group.traverse((obj) => {
      if (obj.geometry) { try { obj.geometry.dispose(); } catch (e) {} }
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => { try { m.dispose(); } catch (e) {} });
        } else {
          try { obj.material.dispose(); } catch (e) {}
        }
      }
    });
    disposables.forEach(d => { try { d.dispose(); } catch (e) {} });
  };

  return group;
}
